#[test]
#[ignore]
fn audit_repeated_reopen() {
    let config = Config::from_env();
    let tmp = tempfile::tempdir().unwrap();
    let rows = fixture(config.rows, config.profile);
    let expected = expected_matches(&rows);
    let mut storage = PartitionManager::open(config.storage(tmp.path())).unwrap();
    for batch in rows.chunks(config.batch_rows) { storage.write_batch(batch).unwrap(); }
    storage.checkpoint().unwrap();
    let targets: Vec<_> = storage.sealed_partitions().iter()
        .chain(std::iter::once(storage.hot_partition()))
        .filter(|p| p.meta.row_count > 0).map(|p| p.meta.path.clone()).collect();
    for path in &targets { IndexBuilder::build_all_indexes(path).unwrap(); }
    storage.compact_eligible_segments().unwrap();
    assert_native(&storage, &expected);
    drop(storage);
    for i in 0..101 {
        let start = Instant::now();
        let storage = PartitionManager::open(config.storage(tmp.path())).unwrap();
        let elapsed = start.elapsed().as_secs_f64()*1000.0;
        assert_eq!(storage.total_rows(), rows.len() as u64);
        if i == 100 { assert_native(&storage, &expected); }
        drop(storage);
        if i != 0 { println!("{}", json!({"kind":"reopen", "iteration":i,"elapsed_ms":elapsed})); }
    }
}

